unsigned checks=0,failures=0;
void Check(bool value,const char* label){++checks;failures+=!value;std::printf("%s %s\n",value?"PASS":"FAIL",label);}
bool Near(double a,double b,double tolerance=1e-5){return std::abs(a-b)<=tolerance;}
Scene Fixture(){
 Scene scene;scene.Settings().name="Powertrain lifecycle fixture";
 auto& ground=scene.CreateObject("ordinary ground");ground.body=SceneBodyComponent{};ground.body->halfExtents={20,.25f,20};ground.transform.position={0,-.25f,0};
 auto& chassis=scene.CreateObject("generic chassis");chassis.body=SceneBodyComponent{};chassis.body->motion=SceneBodyMotion::Dynamic;chassis.body->managed=true;chassis.body->mass=120;chassis.body->halfExtents={.5f,.2f,.8f};chassis.transform.position={0,.55f,0};
 const auto chassisId=chassis.id;for(unsigned n=0;n<2;++n){auto& wheel=scene.CreateObject("external wheel");wheel.parent=chassisId;wheel.wheel=WheelSettings{};wheel.wheel->chassis=chassisId;wheel.wheel->mount={n?.7f:-.7f,0,0};}
 auto& train=scene.Find(chassisId)->powertrain.emplace();PowertrainShaft input;input.name="rotor";input.inertia=.4;input.bearing=chassisId;input.axis={-1,0,0};train.shafts.push_back(input);
 for(uint64_t id:{3,4}){PowertrainShaft port;port.name=id==3?"left":"right";port.kind=PowertrainShaftKind::Wheel;port.target=id;train.shafts.push_back(port);}
 PowertrainSource source;source.name="motor";source.kind=PowertrainSourceKind::Electric;source.maxTorque=80;source.maxPower=3000;train.sources.push_back(source);
 PowertrainLink differential;differential.name="differential";differential.kind=PowertrainLinkKind::Differential;differential.ratio=.2;train.links.push_back(differential);
 return scene;
}
void Tick(RuntimeWorld& world,unsigned count=1){for(unsigned i=0;i<count;++i){world.Physics().ApplyLinearAcceleration(world.RuntimeBody(2),{0,-9.81f,0},1.f/60);world.UpdatePowertrains(1.f/60);world.UpdateWheels(1.f/60);world.ResolvePowertrainLoads(1.f/60);world.Physics().Step(1.f/60);world.PublishWheels();world.PublishPowertrains(1.f/60);}}
std::string Bytes(PowertrainInstance* train){SaveArchive a;if(train)train->Persist(a);return a.bytes;}
