 PowertrainSettings settings;PowertrainShaft shaft;shaft.name="physical";shaft.kind=PowertrainShaftKind::Body;shaft.target=2;shaft.bearing=1;shaft.axis={0,0,1};settings.shafts.push_back(shaft);PowertrainSource source;source.name="custom";source.maxTorque=100;settings.sources.push_back(source);scene.Find(1)->powertrain=settings;
