 const auto a=world.RuntimeBody(1),b=world.RuntimeBody(2);const auto la=world.Physics().GetInertiaWorld(a)*world.Physics().GetAngularVelocity(a),lb=world.Physics().GetInertiaWorld(b)*world.Physics().GetAngularVelocity(b);
