 Check(train->state.shafts[0].angularVelocity>0&&train->state.shafts[0].available,"body rotor observation comes from relative physical angular motion");
 train->command.sources[0].customTorque=0;const auto initial=world.Physics().GetAngularVelocity(b);world.UpdatePowertrains(.02f);world.ResolvePowertrainLoads(.02f);Check(glm::length(world.Physics().GetAngularVelocity(b)-initial)<1e-6f,"zero-source negative control adds no rotor drive");
 auto rotated=scene;const auto orientation=glm::angleAxis(.79f,glm::normalize(glm::vec3(.2f,.7f,.4f)));for(auto& object:rotated.Objects()){object.transform.position=orientation*object.transform.position;object.transform.rotation=orientation;}rotated.Find(2)->body->mass=.02f;RuntimeWorld oblique;oblique.legacyGameplay=false;Check(oblique.Build(rotated,nullptr,error),"light physical flywheel builds in an arbitrary orientation");auto* spinning=oblique.RuntimePowertrain(1);spinning->command.sources[0].customTorque=2;oblique.UpdatePowertrains(.02f);oblique.ResolvePowertrainLoads(.02f);oblique.PublishPowertrains(.02f);const auto oa=oblique.RuntimeBody(1),ob=oblique.RuntimeBody(2);Check(spinning->state.converged&&spinning->state.shafts[0].angularVelocity>0&&glm::length(oblique.Physics().GetInertiaWorld(oa)*oblique.Physics().GetAngularVelocity(oa)+oblique.Physics().GetInertiaWorld(ob)*oblique.Physics().GetAngularVelocity(ob))<1e-5f,"oblique light flywheel retains symmetric mechanical mass and opposite physical torque");
