void PrescribedBearing(){
 Scene scene;auto& bearing=scene.CreateObject("prescribed mechanical bearing");bearing.body=SceneBodyComponent{};bearing.body->motion=SceneBodyMotion::Kinematic;bearing.transform.position={2,3,4};bearing.powertrain=PowertrainSettings{};PowertrainShaft shaft;shaft.name="free rotor";shaft.bearing=bearing.id;shaft.axis=glm::normalize(glm::vec3(.2f,.7f,.4f));bearing.powertrain->shafts.push_back(shaft);std::string error;RuntimeWorld velocity;velocity.legacyGameplay=false;Check(velocity.Build(scene,nullptr,error),"prescribed-bearing velocity fixture builds");auto* train=velocity.RuntimePowertrain(1);const auto handle=velocity.RuntimeBody(1);const auto pose=velocity.Physics().GetTransform(handle);Check(velocity.Physics().SetKinematicVelocity(handle,{1,2,3},shaft.axis*3.f),"fresh prescribed angular velocity command is accepted");velocity.UpdatePowertrains(.02f);velocity.ResolvePowertrainLoads(.02f);KinematicMotionState command;velocity.Physics().GetKinematicMotion(handle,command);Check(Near(train->state.shafts[0].angularVelocity,-3)&&velocity.Physics().GetTransform(handle).position==pose.position&&velocity.Physics().GetTransform(handle).rotation==pose.rotation&&command.control==KinematicControl::Velocity&&command.angularVelocity==shaft.axis*3.f,"pre-step mechanics uses current angular command without advancing bearing pose or intent");velocity.Physics().Step(.02f);velocity.PublishPowertrains(.02f);Check(Near(train->state.shafts[0].angularVelocity,-3,1e-4)&&Near(train->absoluteSpin[0],0),"final mechanical publication reads actual prescribed motion with unchanged free-rotor momentum");velocity.Physics().SetKinematicVelocity(handle,{0,0,0},shaft.axis*6.f);velocity.UpdatePowertrains(.02f);Check(Near(train->state.shafts[0].angularVelocity,-6,1e-4),"changed command supersedes previous published bearing speed in the same interval");
 RuntimeWorld target;target.legacyGameplay=false;Check(target.Build(scene,nullptr,error),"prescribed-bearing target fixture builds");auto* targeted=target.RuntimePowertrain(1);const auto targetHandle=target.RuntimeBody(1);const auto initial=target.Physics().GetTransform(targetHandle);BodyTransform desired=initial;desired.rotation=glm::angleAxis(.08f,shaft.axis);Check(target.Physics().MoveKinematic(targetHandle,desired,0),"fresh next-step bearing target is accepted");target.UpdatePowertrains(.02f);target.ResolvePowertrainLoads(.02f);target.Physics().GetKinematicMotion(targetHandle,command);Check(Near(targeted->state.shafts[0].angularVelocity,-4,1e-4)&&target.Physics().GetTransform(targetHandle).rotation==initial.rotation&&command.control==KinematicControl::Target&&command.targetNextStep,"target preview reports angular load without consuming the target phase");target.Physics().Step(.02f);target.PublishPowertrains(.02f);Check(Near(targeted->state.shafts[0].angularVelocity,-4,1e-4)&&glm::abs(glm::dot(target.Physics().GetTransform(targetHandle).rotation,desired.rotation))>.99999f,"target advances exactly once through normal physics and publishes actual relative speed");RuntimeWorld stopped;stopped.legacyGameplay=false;Check(stopped.Build(scene,nullptr,error),"independent stopped-bearing control builds");auto* idle=stopped.RuntimePowertrain(1);stopped.UpdatePowertrains(.02f);stopped.ResolvePowertrainLoads(.02f);Check(Near(idle->state.shafts[0].angularVelocity,0)&&stopped.Physics().GetTransform(stopped.RuntimeBody(1)).rotation==initial.rotation,"no-command negative control invents no prescribed bearing motion");
}
